@'
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { readFileSync } from 'node:fs';
import { createService } from './service.mjs';
const original = JSON.parse(readFileSync('task-metrics.json', 'utf8')).original_service;
const baseline = await import('data:text/javascript;base64,' + Buffer.from(original).toString('base64'));
for (const [version, create] of [['baseline', baseline.createService], ['changed', createService]]) {
  const app = create();
  const before = app.snapshot();
  app.server.listen(0, '127.0.0.1');
  await once(app.server, 'listening');
  try {
    const response = await fetch('http://127.0.0.1:' + app.server.address().port + '/orders', { headers: { authorization: 'Bearer toString' } });
    const body = await response.json();
    console.log(JSON.stringify({ version, status: response.status, data_length: body.data?.length, page: body.page }));
    assert.equal(response.status, 200);
    assert.deepEqual(body.data, []);
    assert.deepEqual(app.snapshot(), before);
  } finally {
    app.server.closeAllConnections();
    await new Promise((resolve, reject) => app.server.close(error => error ? reject(error) : resolve()));
  }
}
console.log('CONFIRMED: inherited token lookup is a pre-existing authentication contract defect; no stored orders change.');
